<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {scheduleApi} from '../schedules'
const props=defineProps<{state:any;classId:number;view:string}>()
const emit=defineEmits<{create:[id:number];open:[tab:string];rooms:[id:number]}>()
const cl=computed(()=>props.state.classes.find((c:any)=>c.id===props.classId))
const year=computed(()=>props.state.years.find((y:any)=>y.id===cl.value?.year_id))
const terms=computed(()=>props.state.terms.filter((t:any)=>t.year_id===cl.value?.year_id))
const termId=ref(0),date=ref(''),page=ref(1),roster=ref<any>(null),roomData=ref<any>(null),loading=ref(false),error=ref('')
const subjects=computed(()=>props.state.subjects.filter((s:any)=>s.semester_id===termId.value&&props.state.links.some((l:any)=>l.class_id===props.classId&&l.offering_id===s.id)))
const assignments=computed(()=>subjects.value.map((s:any)=>({...s,teacher:props.state.teachers.find((t:any)=>props.state.subject_teachers.some((a:any)=>a.offering_id===s.id&&a.teacher_id===t.id))})))
const homeroom=computed(()=>{const ids=[...new Set(assignments.value.filter((s:any)=>props.state.meetings.some((m:any)=>m.course_offering_id===s.id&&m.day_of_week===7&&m.start_time.slice(0,5)==='10:00')).map((s:any)=>s.teacher?.id).filter(Boolean))];return ids.length===1?props.state.teachers.find((t:any)=>t.id===ids[0])?.name:ids.length?'Review conflicting first lessons':'Not assigned'})
const room=computed(()=>roomData.value?.assignments.find((a:any)=>a.class_id===props.classId&&a.year_id===cl.value?.year_id)?.room_number)
const bookings=computed(()=>roomData.value?.bookings.filter((b:any)=>b.class_id===props.classId&&!b.is_cancelled&&b.starts_on<=date.value&&b.ends_on>=date.value&&b.day_of_week===(new Date(date.value+'T00:00:00Z').getUTCDay()||7))??[])
let request=0
async function load(){if(!cl.value||!date.value)return;const current=++request;loading.value=true;error.value='';try{
 const [r,rooms]=await Promise.all([scheduleApi(`admin/school/classes/${props.classId}/students?date=${date.value}&page=${page.value}`),scheduleApi('admin/school/rooms')]);if(current!==request)return;roster.value=r;roomData.value=rooms
}catch(e){if(current===request){roster.value=null;roomData.value=null;error.value=e instanceof Error?e.message:'Unable to load class details.'}}finally{if(current===request)loading.value=false}}
watch(()=>[props.classId,props.state.revision],()=>{const y=year.value,today=props.state.today;if(!y)return;if(!date.value||date.value<y.start_date||date.value>y.end_date)date.value=today<y.start_date?y.start_date:today>y.end_date?y.end_date:today;page.value=1;if(!terms.value.some((t:any)=>t.id===termId.value))termId.value=terms.value.find((t:any)=>t.start_date<=today&&t.end_date>=today)?.id??terms.value[0]?.id??0;void load()},{immediate:true})
function changeDate(){page.value=1;void load()}
function next(delta:number){page.value+=delta;void load()}
</script>
<template>
<section v-if="cl" class="class-details" :class="{'teacher-view':view==='teachers'}">
 <div v-if="view==='teachers'" class="teacher-toolbar"><strong>Grade {{cl.grade_label}} · Class {{cl.name}}</strong><label>School term<select v-model="termId"><option :value="0">No linked term</option><option v-for="t in terms" :key="t.id" :value="t.id">{{t.name}}</option></select></label><button class="secondary" :disabled="loading" @click="load">Refresh</button></div>
 <template v-else> <div class="class-heading"><div><p class="eyebrow">CLASS WORKSPACE</p><h3>Grade {{cl.grade_label}} · Class {{cl.name}}</h3><p class="muted">{{year?.name}} · {{cl.is_active?'Active':'Inactive'}}</p></div><button class="secondary" :disabled="loading" @click="load">Refresh class</button></div>
 <div class="context"><label>View on date<input v-model="date" type="date" :min="year?.start_date" :max="year?.end_date" @change="changeDate"></label><label>School term<select v-model="termId"><option :value="0">No linked term</option><option v-for="t in terms" :key="t.id" :value="t.id">{{t.name}}</option></select></label></div>
 </template>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="loading" role="status">Loading class details…</p>
 <template v-else-if="!error">
 <div v-if="view==='class'" class="summary-grid"><article><span>Enrolled students</span><strong>{{roster?.total??'—'}}</strong><button class="link" @click="emit('open','roster')">View students →</button></article><article><span>Usual classroom</span><strong>{{room?'Room '+room:'Not assigned'}}</strong><button class="link" @click="emit('open','classrooms')">View room bookings →</button></article><article><span>Homeroom teacher</span><strong>{{homeroom}}</strong><small>Sunday’s 10 AM teacher · selected term</small></article><article><span>Class subjects</span><strong>{{subjects.length}}</strong><button class="link" @click="emit('open','subjects')">Open timetable →</button></article></div>
 <div v-if="view==='class'" class="overview-actions"><button :disabled="!cl.is_active" @click="emit('create',cl.id)">+ Enroll new student</button><button class="secondary" @click="emit('open','members')">Assign existing student</button></div>
 <template v-if="view==='roster'"><div class="roster-heading"><h3>Students <small v-if="roster">({{roster.total}})</small></h3><div><button :disabled="!cl.is_active" @click="emit('create',cl.id)">+ Enroll new student</button><button class="secondary" @click="emit('open','members')">Assign or transfer existing</button></div></div><p v-if="!roster?.students.length" class="muted">No students enrolled on this date. Enroll a new student or assign an existing account.</p><div v-else class="table-scroll"><table><thead><tr><th>Student</th><th>Login ID</th><th>Account</th></tr></thead><tbody><tr v-for="s in roster.students" :key="s.id"><td>{{s.full_name}}</td><td>{{s.login_id}}</td><td>{{s.is_active?'Enabled':'Disabled'}}</td></tr></tbody></table></div><div v-if="roster?.total" class="pager"><button class="secondary" :disabled="page===1" @click="next(-1)">Previous</button><span>Page {{page}} / {{Math.max(1,Math.ceil(roster.total/10))}} · {{roster.total}} students</span><button class="secondary" :disabled="page*10>=roster.total" @click="next(1)">Next</button></div></template>
 <template v-if="view==='teachers'"><div class="teachers-summary"><h3>Subject teachers</h3><p class="muted">Homeroom: <strong>{{homeroom}}</strong></p></div><p v-if="!assignments.length">No subjects linked to this class in this term.</p><div v-else class="table-scroll"><table><thead><tr><th>Subject</th><th>Teacher</th><th>Staff code</th></tr></thead><tbody><tr v-for="s in assignments" :key="s.id"><td>{{s.course_name}}</td><td>{{s.teacher?.name??'Not assigned'}}</td><td>{{s.teacher?.staff_code??'—'}}{{s.teacher&&!s.teacher.is_active?' · Inactive':''}}</td></tr></tbody></table></div><button class="secondary" @click="emit('open','subjects')">Manage subject teachers</button></template>
 <template v-if="view==='classrooms'"><h3>Usual classroom: {{room?'Room '+room:'Not assigned'}}</h3><button @click="emit('rooms',cl.id)">Open room board for this class</button><h3>Special-room bookings · {{date}}</h3><p v-if="!bookings.length" class="muted">No active special-room bookings on this date.</p><article v-for="b in bookings" :key="b.id" class="booking"><strong>Room {{b.room_number}} · {{b.course_name}}</strong><p>{{b.start_time}}–{{b.end_time}} · {{b.teacher_name}}</p></article></template>
 </template>
</section>
</template>
<style scoped>
.class-details{background:white;border:1px solid #dce6df;border-radius:14px;padding:22px;margin:16px 0}.class-heading,.roster-heading,.pager{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}h3{margin:6px 0 12px}.muted,small{font-size:13px;color:#66796f}.context{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0}.context label{font-size:13px;flex:1;min-width:150px}.context input,.context select{width:100%;padding:10px;border:1px solid #bdcfc4;border-radius:8px;background:white;font:inherit;margin:6px 0}.summary-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:20px 0}.summary-grid article{background:#f0f5f1;padding:16px;border-radius:10px;min-width:0}.summary-grid span,.summary-grid strong,.summary-grid small{display:block}.summary-grid span{font-size:12px;color:#607369}.summary-grid strong{font-size:18px;margin:9px 0;overflow-wrap:anywhere}.link{background:transparent;color:#365f50;padding:0;font-size:12px}.roster-heading{margin:24px 0 12px}.roster-heading button{margin:4px;font-size:13px;padding:10px}.overview-actions{display:flex;flex-wrap:wrap;gap:8px}.overview-actions button{font-size:13px;padding:10px 12px}.table-scroll{overflow:auto}td:last-child{white-space:nowrap}table{width:100%;border-collapse:collapse;font-size:14px;text-align:left}th,td{padding:11px;border-bottom:1px solid #e0e8e2}th{background:#f1f5f2;font-size:12px}.pager{margin-top:16px;font-size:12px}.pager button{padding:10px}.booking{border:1px solid #dde6df;border-radius:8px;padding:12px;margin-top:10px}button{width:auto}@media(max-width:600px){.class-details{padding:14px}.summary-grid article{padding:12px}.summary-grid strong{font-size:15px}.class-heading{align-items:start}.roster-heading>div{display:flex;flex-wrap:wrap}.context input{font-size:16px}}

.teacher-view{padding:14px 16px;margin:10px 0}.teacher-toolbar{display:flex;gap:14px;align-items:center;flex-wrap:wrap;padding-bottom:12px;border-bottom:1px solid #e1e9e3}.teacher-toolbar>strong{font-size:15px;margin-right:auto}.teacher-toolbar label{display:flex;gap:8px;align-items:center;font-size:12px;margin:0!important;font-weight:500}.teacher-toolbar select{width:220px;max-width:100%;padding:8px 10px;margin:0;font-size:12px;border:1px solid #bdcfc4;border-radius:7px;background:white;color:#294735;min-height:36px}.teacher-toolbar button{padding:8px 12px;font-size:12px;margin:0!important;min-height:36px}.teachers-summary{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin:12px 0 8px}.teachers-summary h3{font-size:15px;margin:0}.teachers-summary p{margin:0;font-size:12px}.teacher-view th,.teacher-view td{padding:8px 10px;font-size:13px}.teacher-view th{font-size:12px}.teacher-view>.secondary{padding:8px 12px;font-size:12px;margin:12px 0 0}@media(max-width:600px){.teacher-view{padding:12px}.teacher-toolbar{gap:10px}.teacher-toolbar>strong{flex:1}.teacher-toolbar label{order:3;width:100%}.teacher-toolbar select{flex:1;width:0}.teachers-summary{align-items:start}.teacher-view table{min-width:360px}}
</style>
